<?php
declare(strict_types=1);

require_once __DIR__ . '/_gate3_domain.php';

const BE_STARTPARTNER_GATE4_REQUIRED_ITEMS = [
    'terms_confirmed','organizer_linked','contact_confirmed','portal_access_tested',
    'pilot_entitlement_readback','service_scope_consistent','sources_recorded',
    'maintenance_path_agreed','content_rights_confirmed','first_content_prepared',
    'editorial_review_ready','measurement_attribution_ready',
    'distribution_commitment_ready','activation_target_set',
];

const BE_STARTPARTNER_GATE4_REQUIRED_SCHEMA = [
    'startpartner_pilot_onboarding_items' => ['pilot_id','item_key','status','evidence_text','blocker_text','revision'],
    'startpartner_pilot_portal_proofs' => ['pilot_id','organizer_id','proof_kind','status','evidence_json','revision'],
    'startpartner_pilot_content_links' => ['id','pilot_id','organizer_id','submission_id','content_type','status','reporting_target_id','revision'],
    'startpartner_pilot_measurement_preflights' => ['pilot_id','organizer_id','content_link_id','reporting_target_id','status','evidence_json','revision'],
    'startpartner_pilot_distribution_commitments' => ['id','pilot_id','channel','planned_date','target_reference','status','revision'],
    'startpartner_pilot_usages' => ['id','pilot_id','pilot_entitlement_id','content_link_id','usage_kind','period_start','period_end'],
    'startpartner_pilot_operations' => ['operation_id','candidate_id','pilot_id','action','payload_hash','status','candidate_revision_before','pilot_revision_before'],
];

function be_startpartner_gate4_json(array $value): string { return json_encode($value, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR); }
function be_startpartner_gate4_text(mixed $value, string $field, int $max=2048): string { $text=trim((string)$value); if ($text==='') throw new InvalidArgumentException("$field is required."); if (mb_strlen($text)>$max) throw new InvalidArgumentException("$field is too long."); return $text; }
function be_startpartner_gate4_optional_text(mixed $value, int $max=4096): ?string { $text=trim((string)$value); if ($text==='') return null; if (mb_strlen($text)>$max) throw new InvalidArgumentException('Text is too long.'); return $text; }
function be_startpartner_gate4_schema_gaps(PDO $pdo): array { $db=(string)$pdo->query('SELECT DATABASE()')->fetchColumn(); if ($db==='') return ['database'=>['No database selected.']]; $stmt=$pdo->prepare('SELECT TABLE_NAME,COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=:db'); $stmt->execute(['db'=>$db]); $present=[]; foreach ($stmt->fetchAll(PDO::FETCH_ASSOC) as $row) $present[(string)$row['TABLE_NAME']][(string)$row['COLUMN_NAME']]=true; $gaps=[]; foreach (BE_STARTPARTNER_GATE4_REQUIRED_SCHEMA as $table=>$columns) { if (!isset($present[$table])) {$gaps[$table]=['table missing']; continue;} foreach ($columns as $column) if (!isset($present[$table][$column])) $gaps[$table][]=$column; } foreach (['activation_date_local','planned_end_date'] as $column) if (!isset($present['startpartner_pilots'][$column])) $gaps['startpartner_pilots'][]=$column; return $gaps; }
function be_startpartner_gate4_require_schema(PDO $pdo): void { $gaps=be_startpartner_gate4_schema_gaps($pdo); if ($gaps!==[]) throw new RuntimeException('STARTPARTNER_GATE4_SCHEMA_MISSING: '.be_startpartner_gate4_json($gaps)); }
function be_startpartner_gate4_pilot(PDO $pdo,string $pilotId,bool $forUpdate=false): array { $stmt=$pdo->prepare('SELECT p.*,c.revision AS candidate_revision FROM startpartner_pilots p INNER JOIN startpartner_candidates c ON c.id=p.candidate_id WHERE p.id=:id LIMIT 1'.($forUpdate?' FOR UPDATE':'')); $stmt->execute(['id'=>$pilotId]); $row=$stmt->fetch(PDO::FETCH_ASSOC); if (!is_array($row)) throw new RuntimeException('Startpartner pilot not found.'); $row['target_plan_keys']=json_decode((string)$row['target_plan_keys_json'],true,512,JSON_THROW_ON_ERROR); unset($row['target_plan_keys_json']); return $row; }
function be_startpartner_gate4_seed(PDO $pdo,string $pilotId,string $operator): void { $stmt=$pdo->prepare("INSERT INTO startpartner_pilot_onboarding_items (pilot_id,item_key,status,is_required,operator_reference) VALUES (:pilot_id,:item_key,'pending',1,:operator) ON DUPLICATE KEY UPDATE item_key=VALUES(item_key)"); foreach (BE_STARTPARTNER_GATE4_REQUIRED_ITEMS as $item) $stmt->execute(['pilot_id'=>$pilotId,'item_key'=>$item,'operator'=>$operator]); }
function be_startpartner_gate4_date(mixed $value,string $field): string { $text=trim((string)$value); $date=DateTimeImmutable::createFromFormat('!Y-m-d',$text,new DateTimeZone('Europe/Berlin')); $errors=DateTimeImmutable::getLastErrors(); if (!$date || (is_array($errors) && (($errors['warning_count']??0)>0 || ($errors['error_count']??0)>0))) throw new InvalidArgumentException("$field must use YYYY-MM-DD."); return $date->format('Y-m-d'); }
function be_startpartner_gate4_add_months(string $date,int $months): string { $source=new DateTimeImmutable($date,new DateTimeZone('Europe/Berlin')); $day=(int)$source->format('d'); $target=$source->modify('first day of this month')->modify("+$months months"); return $target->setDate((int)$target->format('Y'),(int)$target->format('m'),min($day,(int)$target->format('t')))->format('Y-m-d'); }
function be_startpartner_gate4_state(PDO $pdo,string $pilotId): array { be_startpartner_gate4_require_schema($pdo); $pilot=be_startpartner_gate4_pilot($pdo,$pilotId); be_startpartner_gate4_seed($pdo,$pilotId,'system-readback'); $q=$pdo->prepare('SELECT * FROM startpartner_pilot_onboarding_items WHERE pilot_id=:id ORDER BY id'); $q->execute(['id'=>$pilotId]); $items=$q->fetchAll(PDO::FETCH_ASSOC); $q=$pdo->prepare('SELECT * FROM startpartner_pilot_portal_proofs WHERE pilot_id=:id LIMIT 1'); $q->execute(['id'=>$pilotId]); $portal=$q->fetch(PDO::FETCH_ASSOC); $q=$pdo->prepare('SELECT l.*,s.status AS submission_status,s.title AS submission_title FROM startpartner_pilot_content_links l INNER JOIN submissions s ON s.id=l.submission_id WHERE l.pilot_id=:id ORDER BY l.created_at,l.id'); $q->execute(['id'=>$pilotId]); $links=$q->fetchAll(PDO::FETCH_ASSOC); $q=$pdo->prepare('SELECT * FROM startpartner_pilot_measurement_preflights WHERE pilot_id=:id LIMIT 1'); $q->execute(['id'=>$pilotId]); $measurement=$q->fetch(PDO::FETCH_ASSOC); $q=$pdo->prepare('SELECT * FROM startpartner_pilot_distribution_commitments WHERE pilot_id=:id ORDER BY planned_date,id'); $q->execute(['id'=>$pilotId]); $distribution=$q->fetchAll(PDO::FETCH_ASSOC); $blockers=[]; foreach ($items as $item) if ((int)$item['is_required']===1 && (string)$item['status']!=='complete') $blockers[]=['code'=>'onboarding_'.(string)$item['item_key'],'message'=>(string)($item['blocker_text']?:'Onboardingpunkt ist nicht abgeschlossen.')]; if (!is_array($portal) || (string)$portal['status']!=='ready') $blockers[]=['code'=>'portal_access_not_ready','message'=>'Portalzugang ist nicht belegt.']; $first=null; foreach ($links as $link) if (in_array((string)$link['status'],['editorial_ready','approved'],true)) {$first=$link;break;} if (!is_array($first)) $blockers[]=['code'=>'first_content_not_ready','message'=>'Kein redaktionell bereiter Pilotinhalt ist verknüpft.']; if (!is_array($measurement) || (string)$measurement['status']!=='ready') $blockers[]=['code'=>'measurement_not_ready','message'=>'Messzuordnung ist nicht bereit.']; $distributionReady=false; foreach ($distribution as $row) if (in_array((string)$row['status'],['ready','completed'],true)) {$distributionReady=true;break;} if (!$distributionReady) $blockers[]=['code'=>'distribution_not_ready','message'=>'Partnerdistribution ist nicht vorbereitet.']; return ['pilot'=>$pilot,'onboarding_items'=>$items,'portal_proof'=>is_array($portal)?$portal:null,'content_links'=>$links,'first_content'=>$first,'measurement_preflight'=>is_array($measurement)?$measurement:null,'distribution_commitments'=>$distribution,'activation_ready'=>$blockers===[],'blockers'=>$blockers]; }
function be_startpartner_gate4_update_item(PDO $pdo,string $pilotId,array $input): array { $operator=be_startpartner_gate2_operator_name($input['operator_name']??null); $item=be_startpartner_gate4_text($input['item_key']??null,'item_key',64); if (!in_array($item,BE_STARTPARTNER_GATE4_REQUIRED_ITEMS,true)) throw new InvalidArgumentException('Unknown onboarding item.'); $status=strtolower(be_startpartner_gate4_text($input['status']??null,'status',16)); if (!in_array($status,['pending','complete','blocked'],true)) throw new InvalidArgumentException('Invalid onboarding status.'); $evidence=be_startpartner_gate4_optional_text($input['evidence_text']??null); $blocker=be_startpartner_gate4_optional_text($input['blocker_text']??null); if ($status==='complete' && $evidence===null) throw new DomainException('Completed onboarding items require evidence.'); if ($status==='blocked' && $blocker===null) throw new DomainException('Blocked onboarding items require blocker_text.'); be_startpartner_gate4_seed($pdo,$pilotId,$operator); $stmt=$pdo->prepare('UPDATE startpartner_pilot_onboarding_items SET status=:status,evidence_text=:evidence,blocker_text=:blocker,operator_reference=:operator,completed_at=CASE WHEN :complete=1 THEN CURRENT_TIMESTAMP ELSE NULL END,revision=revision+1 WHERE pilot_id=:pilot_id AND item_key=:item_key'); $stmt->execute(['status'=>$status,'evidence'=>$evidence,'blocker'=>$status==='blocked'?$blocker:null,'operator'=>$operator,'complete'=>$status==='complete'?1:0,'pilot_id'=>$pilotId,'item_key'=>$item]); return be_startpartner_gate4_state($pdo,$pilotId); }
function be_startpartner_gate4_portal_proof(PDO $pdo,string $pilotId,array $input): array { $pilot=be_startpartner_gate4_pilot($pdo,$pilotId); $operator=be_startpartner_gate2_operator_name($input['operator_name']??null); $kind=strtolower(be_startpartner_gate4_text($input['proof_kind']??null,'proof_kind',32)); $status=strtolower(be_startpartner_gate4_text($input['status']??null,'status',16)); if (!in_array($kind,['session_readback','no_send_fixture'],true) || !in_array($status,['ready','blocked'],true)) throw new InvalidArgumentException('Invalid portal proof.'); $evidence=is_array($input['evidence']??null)?$input['evidence']:[]; if ($evidence===[]) throw new DomainException('Portal proof evidence is required.'); $stmt=$pdo->prepare('INSERT INTO startpartner_pilot_portal_proofs (pilot_id,organizer_id,proof_kind,status,session_reference,evidence_json,checked_at,operator_reference) VALUES (:pilot_id,:organizer_id,:proof_kind,:status,:session_reference,:evidence_json,CURRENT_TIMESTAMP,:operator) ON DUPLICATE KEY UPDATE proof_kind=VALUES(proof_kind),status=VALUES(status),session_reference=VALUES(session_reference),evidence_json=VALUES(evidence_json),checked_at=CURRENT_TIMESTAMP,operator_reference=VALUES(operator_reference),revision=revision+1'); $stmt->execute(['pilot_id'=>$pilotId,'organizer_id'=>(int)$pilot['organizer_id'],'proof_kind'=>$kind,'status'=>$status,'session_reference'=>be_startpartner_gate4_optional_text($input['session_reference']??null,191),'evidence_json'=>be_startpartner_gate4_json($evidence),'operator'=>$operator]); return be_startpartner_gate4_state($pdo,$pilotId); }
function be_startpartner_gate4_link_content(PDO $pdo,string $pilotId,array $input): array { $pilot=be_startpartner_gate4_pilot($pdo,$pilotId); $operator=be_startpartner_gate2_operator_name($input['operator_name']??null); $submissionId=filter_var($input['submission_id']??null,FILTER_VALIDATE_INT); if ($submissionId===false || $submissionId<1) throw new InvalidArgumentException('submission_id is invalid.'); $q=$pdo->prepare('SELECT id,organizer_id,submission_kind,status FROM submissions WHERE id=:id LIMIT 1'); $q->execute(['id'=>(int)$submissionId]); $submission=$q->fetch(PDO::FETCH_ASSOC); if (!is_array($submission) || (int)$submission['organizer_id']!==(int)$pilot['organizer_id']) throw new DomainException('Submission organizer does not match pilot organizer.'); if (!in_array((string)$submission['submission_kind'],['event','activity'],true) || !in_array((string)$submission['status'],['pending_review','paid','in_review'],true)) throw new DomainException('Submission is not pilot-compatible.'); $linkId=be_cc_uuid(); $target='organizer-'.substr(hash('sha256','organizer:'.(int)$pilot['organizer_id']),0,16); $status=in_array((string)$submission['status'],['paid','in_review'],true)?'editorial_ready':'prepared'; $stmt=$pdo->prepare('INSERT INTO startpartner_pilot_content_links (id,pilot_id,organizer_id,submission_id,content_type,status,source_reference,reporting_target_id,editorial_ready_at,operator_reference) VALUES (:id,:pilot_id,:organizer_id,:submission_id,:content_type,:status,:source_reference,:target,CASE WHEN :ready=1 THEN CURRENT_TIMESTAMP ELSE NULL END,:operator) ON DUPLICATE KEY UPDATE pilot_id=VALUES(pilot_id),organizer_id=VALUES(organizer_id),content_type=VALUES(content_type),status=VALUES(status),reporting_target_id=VALUES(reporting_target_id),editorial_ready_at=VALUES(editorial_ready_at),operator_reference=VALUES(operator_reference),revision=revision+1'); $stmt->execute(['id'=>$linkId,'pilot_id'=>$pilotId,'organizer_id'=>(int)$pilot['organizer_id'],'submission_id'=>(int)$submissionId,'content_type'=>(string)$submission['submission_kind'],'status'=>$status,'source_reference'=>'submission:'.(int)$submissionId,'target'=>$target,'ready'=>$status==='editorial_ready'?1:0,'operator'=>$operator]); return be_startpartner_gate4_state($pdo,$pilotId); }
function be_startpartner_gate4_measurement(PDO $pdo,string $pilotId,array $input): array { $pilot=be_startpartner_gate4_pilot($pdo,$pilotId); $operator=be_startpartner_gate2_operator_name($input['operator_name']??null); $contentId=be_startpartner_gate4_text($input['content_link_id']??null,'content_link_id',36); $status=strtolower(be_startpartner_gate4_text($input['status']??null,'status',16)); if (!in_array($status,['pending','ready','blocked'],true)) throw new InvalidArgumentException('Invalid measurement status.'); $evidence=is_array($input['evidence']??null)?$input['evidence']:[]; if ($status==='ready' && $evidence===[]) throw new DomainException('Ready measurement requires evidence.'); $q=$pdo->prepare('SELECT * FROM startpartner_pilot_content_links WHERE id=:id AND pilot_id=:pilot_id AND organizer_id=:organizer_id LIMIT 1'); $q->execute(['id'=>$contentId,'pilot_id'=>$pilotId,'organizer_id'=>(int)$pilot['organizer_id']]); $link=$q->fetch(PDO::FETCH_ASSOC); if (!is_array($link)) throw new DomainException('Pilot content link not found.'); $stmt=$pdo->prepare('INSERT INTO startpartner_pilot_measurement_preflights (pilot_id,organizer_id,content_link_id,reporting_target_type,reporting_target_id,status,evidence_json,checked_at,operator_reference) VALUES (:pilot_id,:organizer_id,:content_link_id,"organizer",:target,:status,:evidence,CASE WHEN :pending=1 THEN NULL ELSE CURRENT_TIMESTAMP END,:operator) ON DUPLICATE KEY UPDATE content_link_id=VALUES(content_link_id),reporting_target_id=VALUES(reporting_target_id),status=VALUES(status),evidence_json=VALUES(evidence_json),checked_at=VALUES(checked_at),operator_reference=VALUES(operator_reference),revision=revision+1'); $stmt->execute(['pilot_id'=>$pilotId,'organizer_id'=>(int)$pilot['organizer_id'],'content_link_id'=>$contentId,'target'=>(string)$link['reporting_target_id'],'status'=>$status,'evidence'=>be_startpartner_gate4_json($evidence),'pending'=>$status==='pending'?1:0,'operator'=>$operator]); return be_startpartner_gate4_state($pdo,$pilotId); }
function be_startpartner_gate4_distribution(PDO $pdo,string $pilotId,array $input): array { be_startpartner_gate4_pilot($pdo,$pilotId); $operator=be_startpartner_gate2_operator_name($input['operator_name']??null); $status=strtolower(be_startpartner_gate4_text($input['status']??'planned','status',16)); if (!in_array($status,['planned','ready','completed','blocked'],true)) throw new InvalidArgumentException('Invalid distribution status.'); $stmt=$pdo->prepare('INSERT INTO startpartner_pilot_distribution_commitments (pilot_id,channel,planned_date,target_reference,status,evidence_text,operator_reference) VALUES (:pilot_id,:channel,:planned_date,:target_reference,:status,:evidence_text,:operator)'); $stmt->execute(['pilot_id'=>$pilotId,'channel'=>be_startpartner_gate4_text($input['channel']??null,'channel',64),'planned_date'=>be_startpartner_gate4_date($input['planned_date']??null,'planned_date'),'target_reference'=>be_startpartner_gate4_text($input['target_reference']??null,'target_reference',2048),'status'=>$status,'evidence_text'=>be_startpartner_gate4_optional_text($input['evidence_text']??null),'operator'=>$operator]); return be_startpartner_gate4_state($pdo,$pilotId); }
function be_startpartner_gate4_activate(PDO $pdo,string $pilotId,array $input): array { $operationId=be_startpartner_gate2_operation_id($input['operation_id']??null); $operator=be_startpartner_gate2_operator_name($input['operator_name']??null); $expectedCandidate=be_startpartner_gate2_expected_revision($input['expected_revision']??null); $expectedPilot=filter_var($input['expected_pilot_revision']??null,FILTER_VALIDATE_INT); if ($expectedPilot===false || $expectedPilot<1) throw new InvalidArgumentException('expected_pilot_revision must be positive.'); $localDate=be_startpartner_gate4_date($input['activation_date_local']??null,'activation_date_local'); $endDate=be_startpartner_gate4_add_months($localDate,6); $payloadHash=be_startpartner_gate2_payload_hash($pilotId,'gate4.activate',$input); $pdo->beginTransaction(); try { $pilot=be_startpartner_gate4_pilot($pdo,$pilotId,true); $candidateId=(string)$pilot['candidate_id']; $q=$pdo->prepare('SELECT * FROM startpartner_pilot_operations WHERE operation_id=:id FOR UPDATE'); $q->execute(['id'=>$operationId]); $op=$q->fetch(PDO::FETCH_ASSOC); if (is_array($op)) { if ((string)$op['candidate_id']!==$candidateId || (string)$op['pilot_id']!==$pilotId || !hash_equals((string)$op['payload_hash'],$payloadHash)) throw new BeStartpartnerConflictException('operation_id payload conflict.',be_startpartner_gate4_state($pdo,$pilotId)); if ((string)$op['status']==='completed') {$result=json_decode((string)$op['result_json'],true,512,JSON_THROW_ON_ERROR);$pdo->commit();return $result+['idempotent_replay'=>true];} throw new BeStartpartnerConflictException('Operation already running.',be_startpartner_gate4_state($pdo,$pilotId)); } if ((int)$pilot['candidate_revision']!==$expectedCandidate || (int)$pilot['revision']!==(int)$expectedPilot) throw new BeStartpartnerConflictException('Candidate or pilot revision changed.',be_startpartner_gate4_state($pdo,$pilotId)); if (!in_array((string)$pilot['status'],['onboarding','activation_ready'],true)) throw new DomainException('Pilot is not activatable.'); $pdo->prepare('INSERT INTO startpartner_pilot_operations (operation_id,candidate_id,pilot_id,action,payload_hash,status,candidate_revision_before,pilot_revision_before) VALUES (:operation_id,:candidate_id,:pilot_id,"gate4.activate",:payload_hash,"started",:candidate_revision,:pilot_revision)')->execute(['operation_id'=>$operationId,'candidate_id'=>$candidateId,'pilot_id'=>$pilotId,'payload_hash'=>$payloadHash,'candidate_revision'=>$expectedCandidate,'pilot_revision'=>(int)$expectedPilot]); $state=be_startpartner_gate4_state($pdo,$pilotId); if (!$state['activation_ready']) throw new DomainException('Activation blockers remain: '.be_startpartner_gate4_json($state['blockers'])); $content=$state['first_content']; $q=$pdo->prepare('SELECT * FROM startpartner_pilot_entitlements WHERE pilot_id=:id LIMIT 1 FOR UPDATE');$q->execute(['id'=>$pilotId]);$entitlement=$q->fetch(PDO::FETCH_ASSOC); if (!is_array($entitlement) || (string)$entitlement['status']!=='pending_activation') throw new DomainException('Pilot entitlement is not pending_activation.'); $q=$pdo->prepare('SELECT * FROM submissions WHERE id=:id LIMIT 1 FOR UPDATE');$q->execute(['id'=>(int)$content['submission_id']]);$submission=$q->fetch(PDO::FETCH_ASSOC); if (!is_array($submission) || !in_array((string)$submission['status'],['paid','in_review'],true)) throw new DomainException('First submission is not editorially ready.'); $startUtc=(new DateTimeImmutable($localDate.' 00:00:00',new DateTimeZone('Europe/Berlin')))->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s'); $endUtc=(new DateTimeImmutable($endDate.' 23:59:59',new DateTimeZone('Europe/Berlin')))->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s'); $pdo->prepare("UPDATE startpartner_pilots SET status='active',health='green',activation_ready_at=COALESCE(activation_ready_at,CURRENT_TIMESTAMP),activated_at=:start,activation_date_local=:local_date,planned_end_date=:end_date,starts_at=:start,ends_at=:end,revision=revision+1 WHERE id=:id AND revision=:revision")->execute(['start'=>$startUtc,'local_date'=>$localDate,'end_date'=>$endDate,'end'=>$endUtc,'id'=>$pilotId,'revision'=>(int)$expectedPilot]); $pdo->prepare("UPDATE startpartner_pilot_scopes SET status='active' WHERE pilot_id=:id AND status='planned'")->execute(['id'=>$pilotId]); $pdo->prepare("UPDATE startpartner_pilot_entitlements SET status='active',starts_at=:start,ends_at=:end,revision=revision+1 WHERE id=:id AND status='pending_activation'")->execute(['start'=>$startUtc,'end'=>$endUtc,'id'=>(string)$entitlement['id']]); $pdo->prepare("UPDATE submissions SET status='approved',review_started_at=COALESCE(review_started_at,CURRENT_TIMESTAMP),approved_at=COALESCE(approved_at,CURRENT_TIMESTAMP),updated_at=CURRENT_TIMESTAMP WHERE id=:id")->execute(['id'=>(int)$content['submission_id']]); $pdo->prepare("UPDATE startpartner_pilot_content_links SET status='approved',approved_at=CURRENT_TIMESTAMP,revision=revision+1 WHERE id=:id")->execute(['id'=>(string)$content['id']]); $pdo->prepare("UPDATE startpartner_candidate_reservations SET status='released',released_at=CURRENT_TIMESTAMP,release_reference=:reference WHERE id=:id AND status='active'")->execute(['reference'=>'pilot_activation:'.$operationId,'id'=>(int)$pilot['reservation_id']]); $pdo->prepare('UPDATE startpartner_candidates SET revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE id=:id')->execute(['id'=>$candidateId]); $usage=(string)$content['content_type']==='activity'?'activity_presence':'event_publication'; $pdo->prepare('INSERT INTO startpartner_pilot_usages (pilot_id,pilot_entitlement_id,content_link_id,usage_kind,units,period_start,period_end,operator_reference) VALUES (:pilot_id,:entitlement_id,:content_link_id,:usage_kind,1,:period_start,:period_end,:operator)')->execute(['pilot_id'=>$pilotId,'entitlement_id'=>(string)$entitlement['id'],'content_link_id'=>(string)$content['id'],'usage_kind'=>$usage,'period_start'=>$localDate,'period_end'=>$endDate,'operator'=>$operator]); $pdo->prepare('INSERT INTO startpartner_pilot_events (pilot_id,event_type,actor_reference,payload_json) VALUES (:pilot_id,"gate4_activated",:actor,:payload)')->execute(['pilot_id'=>$pilotId,'actor'=>$operator,'payload'=>be_startpartner_gate4_json(['operation_id'=>$operationId,'activation_date_local'=>$localDate,'planned_end_date'=>$endDate,'content_link_id'=>$content['id'],'submission_id'=>(int)$content['submission_id']])]); $result=be_startpartner_gate4_state($pdo,$pilotId); $pdo->prepare('UPDATE startpartner_pilot_operations SET status="completed",result_json=:result,candidate_revision_after=:candidate_after,pilot_revision_after=:pilot_after,completed_at=CURRENT_TIMESTAMP WHERE operation_id=:id')->execute(['result'=>be_startpartner_gate4_json($result),'candidate_after'=>$expectedCandidate+1,'pilot_after'=>(int)$expectedPilot+1,'id'=>$operationId]); $pdo->commit(); return $result; } catch (Throwable $error) {if ($pdo->inTransaction()) $pdo->rollBack(); throw $error;} }
